    const f = element('form', '', details);
    element('span', 'MyAnimeList ID: ', f);

    mal = element('input', '', f);
    mal.type = 'number';
    mal.placeholder = 'Anime ID';
    mal.style.width = '100px';

    element('button', 'Save / Retry', f).type = 'submit';

    f.addEventListener('submit', e => {
      e.preventDefault();

      const id = Number(mal.value);

      if (Number.isInteger(id) && id > 0) {
        save('nm.intro.mal.' + show, id);
      }

      epoch++;
      busy = false;
      attempted = false;
      range = null;
      done = false;
      pending = null;
      note = '';
      lookupError = '';
      testFeedback = '';

      getRange();
      status();
    });

    const manual = element('form', '', details);

    element(
      'p',
      'Opening start/end for this episode (seconds or m:ss). Save arms automatic skipping when playback reaches the range.',
      manual
    );

    a = element('input', '', manual);
    a.placeholder = 'Start';
    a.style.width = '100px';

    b = element('input', '', manual);
    b.placeholder = 'End';
    b.style.width = '100px';

    element(
      'button',
      'Save episode times',
      manual
    ).type = 'submit';

    manual.addEventListener('submit', e => {
      e.preventDefault();

      const r = valid(parse(a.value), parse(b.value));

      if (!r || !show || !ep) {
        label.textContent =
          'Enter valid opening times for an episode.';
        return;
      }

      epoch++;
      busy = false;
      range = r;
      done = false;
      pending = null;
      note = '';
      testFeedback = '';

      save('nm.intro.times.' + show + '.' + ep, r);

      maybeSkip();
      status();
    });

    const test = element(
      'button',
      'Test seek +10 seconds',
      details
    );

    test.type = 'button';

    test.addEventListener('click', () => {
      if (!protocol || !duration || position === null) {
        label.textContent =
          'Seek test unavailable: no playback timing received yet.';
        return;
      }

      if (pending) return;

      seek(Math.min(position + 10, duration - 1), true);
      status();
    });

    const report = element(
      'button',
      'Show diagnostics',
      details
    );

    report.type = 'button';

    diag = element('textarea', '', details);
    diag.readOnly = true;

    diag.style.cssText =
      'display:none;width:100%;height:150px;' +
      'color:white;background:#111';

    report.addEventListener('click', () => {
      diag.value =
        `Notme intro 1.2\n` +
        `Anime names: ${detectedNames.join(' / ')}\n` +
        `MAL ID: ${detectedMal || 'unknown'}\n` +
        `Lookup stage: ${lookupStage || 'none'}\n` +
        `Lookup error: ${lookupError || 'none'}\n` +
        `Episode: ${ep}\n` +
        `Timing messages: ${messageCount}\n` +
        `Protocol: ${protocol || 'none'}\n` +
        `Message origin: ${origin || 'none'}\n` +
        `Position: ${position}\n` +
        `Duration: ${duration}\n` +
        `Opening: ${JSON.stringify(range)}\n` +
        `Recent messages:\n${recent.join('\n')}`;

      diag.style.display = 'block';
      diag.focus();
      diag.select();
    });
  }

  function sync() {
    const w = document.querySelector('#watch-main');

    const selected = document.querySelector(
      '#w-episodes a.active[data-num]'
    );

    const next =
      document.querySelector('#player iframe') ||
      document.querySelector('#player-wrapper iframe');

    const s = w && w.getAttribute('data-id') || '';

    const e =
      Number(selected && selected.getAttribute('data-num')) ||
      Number(
        (location.pathname.match(/\/ep-([\d.]+)/) || [])[1]
      ) ||
      Number(w && w.getAttribute('data-ep-name'));

    const nextKey =
      s + ':' + e + ':' +
      (next && next.getAttribute('src') || '');

    if (next !== frame || nextKey !== key) {
      frame = next;
      key = nextKey;
      show = s;
      ep = e;
      epoch++;

      position = null;
      duration = 0;
      paused = null;
      protocol = '';
      origin = '';
      range = null;
      done = false;
      pending = null;
      busy = false;
      attempted = false;
      messageCount = 0;
      recent = [];
      note = '';
      testFeedback = '';
      lookupStage = '';
      lookupError = '';
      detectedNames = [];
      detectedMal = 0;

      if (mal) {
        mal.value = read('nm.intro.mal.' + show) || '';
      }

      if (a) a.value = '';
      if (b) b.value = '';
    }

    makeUI();

    if (pending && Date.now() > pending.until) {
      if (pending.test) {
        testFeedback = 'Test seek not confirmed.';
      } else {
        done = true;
        note = 'Seek not confirmed. Open Show diagnostics.';
      }

      pending = null;
    }

    getRange();
    status();
  }

  async function json(url) {
    const controller = new AbortController();

    const t = setTimeout(
      () => controller.abort(),
      15000
    );

    try {
      const r = await fetch(url, {
        signal: controller.signal,
        credentials: 'omit'
      });

      if (!r.ok) throw Error(r.status);

      return await r.json();
    } finally {
      clearTimeout(t);
    }
  }

  async function getRange() {
    if (
      range ||
      !show ||
      !Number.isInteger(ep) ||
      ep < 1 ||
      !protocol ||
      !duration
    ) return;

    const manual = read(
      'nm.intro.times.' + show + '.' + ep
    );

    if (manual) {
      range = valid(manual.start, manual.end);
      if (range) return;
    }

    try {
      const manager =
        window.jQuery &&
        window.jQuery('#watch-main').data('WatchManager');

      const r =
        manager &&
        manager.Xr &&
        manager.Xr.intro;

      if (Array.isArray(r)) {
        range = valid(r[0], r[1]);
        if (range) return;
      }
    } catch (_) {}

    if (busy || attempted) return;

    busy = true;
    attempted = true;

    const token = epoch;

    try {
      const h =
        document.querySelector('#watch-main h1.title') ||
        document.querySelector('h1');

      const names = h
        ? [h.getAttribute('data-jp'), h.textContent]
            .filter(Boolean)
            .map(s => String(s)
              .replace(
                /\s+(?:Episode|Ep\.?)\s+\d+(?:\.\d+)?(?:\s*[-–—:].*)?\s*$/i,
                ''
              )
              .trim())
            .filter(Boolean)
        : [];

      detectedNames = names;

      let id =
        Number(read('nm.intro.mal.' + show)) ||
        names.map(n => known[norm(n)]).find(Boolean);

      if (!id) {
        if (!names.length) throw Error('missing title');

        lookupStage = 'Jikan anime identification';

        const data = await json(
          'https://api.jikan.moe/v4/anime?limit=10&q=' +
          encodeURIComponent(names[0])
        );

        if (token !== epoch) return;

        const exact = (data.data || []).filter(c =>
          [
            c.title,
            c.title_english,
            ...(c.title_synonyms || []),
            ...(c.titles || []).map(t => t.title)
          ].some(t =>
            names.some(n =>
              norm(t) && norm(t) === norm(n)
            )
          )
        );

        if (exact.length !== 1) {
          note =
            'Choose the correct MyAnimeList ID in settings, then Save / Retry.';
          return;
        }

        id = exact[0].mal_id;
      }

      detectedMal = id;
      save('nm.intro.mal.' + show, id);

      if (mal) mal.value = id;

      lookupStage = 'AniSkip opening timestamps';

      const result = await json(
        `https://api.aniskip.com/v2/skip-times/${id}/${ep}` +
        `?types%5B%5D=op&episodeLength=${duration.toFixed(3)}`
      );

      if (token !== epoch) return;

      const candidates = (result.results || [])
        .filter(r =>
          r.skipType === 'op' &&
          r.interval &&
          Math.abs(Number(r.episodeLength) - duration) <= 6
        )
        .sort((a, b) =>
          Math.abs(Number(a.episodeLength) - duration) -
          Math.abs(Number(b.episodeLength) - duration)
        );

      for (const r of candidates) {
        range = valid(
          r.interval.startTime,
          r.interval.endTime
        );

        if (range) break;
      }

      if (!range) {
        note =
          'No matching intro times. You can enter times for this episode.';
      }
    } catch (error) {
      if (token === epoch) {
        lookupError = String(
          error && error.message || error
        );

        note =
          'Lookup failed at ' +
          (lookupStage || 'anime identification') +
          ': ' +
          lookupError +
          '. Use Save / Retry.';
      }
    } finally {
      if (token === epoch) {
        busy = false;
        maybeSkip();
        status();
      }
    }
  }

  function seek(target, test) {
    if (
      !frame ||
      !protocol ||
      position === null ||
      !duration ||
      pending
    ) return;

    if (!test) {
      note = '';
    } else {
      testFeedback = '';
    }

    const command = protocol === 'echo'
      ? {
          channel: 'megacloud',
          event: 'seek',
          time: target
        }
      : {
          cmd: 'SEEK',
          value: target
        };

    try {
      frame.contentWindow.postMessage(
        JSON.stringify(command),
        origin
      );

      pending = {
        from: position,
        target,
        test,
        until: Date.now() + 7000
      };
    } catch (_) {
      note = 'Could not send the seek command.';
      done = true;
    }
  }

  function maybeSkip() {
    if (pending) {
      if (
        position >= pending.target - 0.8 &&
        position - pending.from > 2
      ) {
        const test = pending.test;
        pending = null;

        if (!test) {
          done = true;
          note = 'Intro skipped — position confirmed.';
        } else {
          testFeedback =
            'Seek test passed — position confirmed.';
        }
      }

      return;
    }

    if (
      !range ||
      done ||
      paused === true ||
      position === null ||
      !duration
    ) return;

    if (position >= range.end) {
      done = true;
      note = 'Opening already passed.';
      return;
    }

    if (position >= range.start) {
      seek(range.end, false);
    }
  }

  function onMessage(e) {
    let m = e.data;

    try {
      if (typeof m === 'string') m = JSON.parse(m);
    } catch (_) {
      return;
    }

    if (!m || typeof m !== 'object') return;

    if (
      m.channel === 'megacloud' ||
      m.event === 'PLAY_TIMING'
    ) {
      recent.push(
        `${e.origin} ` +
        `${e.source === (frame && frame.contentWindow) ? 'player' : 'other frame'} ` +
        `${m.channel || ''}/${m.event || ''}`
      );

      recent = recent.slice(-6);
    }

    if (
      !frame ||
      e.source !== frame.contentWindow ||
      !/^https?:\/\//.test(e.origin)
    ) return;

    let expected = '';

    try {
      expected = new URL(
        frame.getAttribute('src'),
        location.href
      ).origin;
    } catch (_) {}

    if (
      e.origin !== expected &&
      !/^https:\/\/(?:[\w-]+\.)*echovideo\.ru$/i.test(e.origin)
    ) return;

    let t, d;

    if (
      m.channel === 'megacloud' &&
      ['time', 'play', 'pause', 'state'].includes(m.event)
    ) {
      t = Number(m.time);
      d = Number(m.duration);

      if (
        !Number.isFinite(t) ||
        !Number.isFinite(d) ||
        d <= 0
      ) return;

      protocol = 'echo';

      if (m.event === 'play') paused = false;
      if (m.event === 'pause') paused = true;

      if (typeof m.paused === 'boolean') {
        paused = m.paused;
      }
    } else if (
      m.event === 'PLAY_TIMING' &&
      m.data
    ) {
      t = Number(m.data.position);
      d = Number(m.data.duration);

      if (
        !Number.isFinite(t) ||
        !Number.isFinite(d) ||
        d <= 0
      ) return;

      protocol = 'legacy';

      if (typeof m.data.paused === 'boolean') {
        paused = m.data.paused;
      }
    } else {
      return;
    }

    if (t < 0) return;

    origin = e.origin;
    position = t;
    duration = d;
    messageCount++;

    getRange();
    maybeSkip();
    status();
  }

  window.addEventListener('message', onMessage);

  window.addEventListener('pagehide', () => {
    clearInterval(timer);
    window.removeEventListener('message', onMessage);
  }, { once: true });

  sync();
  timer = setInterval(sync, 1500);
})();
